import java.util.Optional;
import java.util.TreeMap;

/** A sheet: everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The keys of the dated settings: each value is kept from its from-date. */
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String FLOOR = "floor";
    public static final String TERMS = "terms";
    public static final String LATE_PCT = "late-pct";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";
    public static final String NOTE_THRESHOLD = "note-threshold";
    public static final String REVIEW_THRESHOLD = "review-threshold";
    /** The rounding mode: half-up or half-even; none (null) leaves the policy date to decide. */
    public static final String ROUNDING = "rounding";
    public static final List<String> ROUNDING_MODES = List.of("half-up", "half-even");
    /** The kinds a proof can be: a proof added with none chosen is a receipt. */
    public static final List<String> PROOF_KINDS = List.of("receipt", "photo");
    /** The prefix of a grade's grace days key (grace-A, grace-B, grace-C). */
    public static final String GRACE = "grace";

    /** The actions the permission matrix decides, each with the roles that may take it when its entry is blank. */
    public static final Map<String, String> STANDING_PERMISSIONS = Map.of("open", "clerk,steward", "settle",
            "clerk,steward", "void", "clerk,steward", "reassign", "steward", "close", "clerk,steward", "reopen",
            "steward");
    public static final List<String> PERMISSION_ACTIONS = List.of("open", "settle", "void", "reassign", "close",
            "reopen");

    /** The sheet's starting values, in force before a key's first from-date: none for a key not listed. */
    private static final Map<String, String> STARTING = Map.of(FLOOR, "1.00", TERMS, "14", LATE_PCT, "0.00");

    @Id

    public void setToday(LocalDate today) {
        this.today = today;
    }

    /** The key of a grade's own terms. */
    public static String gradeTermsKey(String grade) {
        return TERMS + "-" + grade;
    }

    /** The key of a grade's own proof threshold (proof-threshold-A, proof-threshold-B, proof-threshold-C). */
    public static String gradeProofThresholdKey(String grade) {
        return PROOF_THRESHOLD + "-" + grade;
    }

    /** The key of a grade's grace days. */
    public static String gradeGraceKey(String grade) {
        return GRACE + "-" + grade;
    }

    /**
     * Record a dated setting's value from the date (null: no limit or cap), replacing the value already recorded from
     * that date; the other values recorded are kept.
     */
    public void record(String key, LocalDate from, String value) {
        dated.stream().filter(d -> d.getKey().equals(key) && d.getFromDate().equals(from)).findFirst()
                .ifPresentOrElse(d -> d.setValue(value), () -> dated.add(new DatedSetting(this, key, from, value)));
    }

    /** Each dated setting's recorded values by key, from-date first to last. */
    public Map<String, List<DatedSetting>> datedSettings() {
        Map<String, List<DatedSetting>> byKey = new TreeMap<>();
        dated.stream().sorted(Comparator.comparing(DatedSetting::getFromDate))
                .forEach(d -> byKey.computeIfAbsent(d.getKey(), k -> new ArrayList<>()).add(d));
        return byKey;
    }

    /**
     * The value of a dated setting in force on the date: the one with the latest from-date on or before it, else the
     * sheet's starting value; empty when that is none.
     */
    public Optional<String> valueOn(String key, LocalDate date) {
        return dated.stream()
                .filter(d -> d.getKey().equals(key) && !d.getFromDate().isAfter(date))
                .max(Comparator.comparing(DatedSetting::getFromDate))
                .map(d -> Optional.ofNullable(d.getValue()))
                .orElseGet(() -> Optional.ofNullable(STARTING.get(key)));
    }

    private Optional<BigDecimal> decimalOn(String key, LocalDate date) {
        return valueOn(key, date).map(v -> new BigDecimal(v).setScale(2, RoundingMode.UNNECESSARY));
    }

    /** The highest due a clerk may settle, in force on the sheet's today; null when there is no limit. */
    public BigDecimal getClerkLimit() {
        return decimalOn(CLERK_LIMIT, today).orElse(null);
    }

    /** The least a live due of a claim dated on the date can be. */
    public BigDecimal floorOn(LocalDate date) {
        return decimalOn(FLOOR, date).orElseThrow();
    }

    /** The most a person's due-total can be, in force on the sheet's today; null when there is no cap. */
    public BigDecimal getCap() {
        return decimalOn(CAP, today).orElse(null);
    }

    /**
     * The due above which a claim dated on the date cannot be settled or approved without a proof; null when there is
     * no threshold then.
     */
    public BigDecimal proofThresholdOn(LocalDate date) {
        return decimalOn(PROOF_THRESHOLD, date).orElse(null);
    }

    /**
     * The proof threshold for a claim dated on the date of a person of the grade (the one in force on the claim's
     * date): the grade's own in force on the date when one is set, else the sheet's; null when there is none then.
     */
    public BigDecimal proofThresholdFor(String grade, LocalDate date) {
        return grade == null ? proofThresholdOn(date)
                : decimalOn(gradeProofThresholdKey(grade), date).orElseGet(() -> proofThresholdOn(date));
    }

    /**
     * The due above which a claim dated on the date cannot be opened with an empty note; null when there is no
     * threshold then.
     */
    public BigDecimal noteThresholdOn(LocalDate date) {
        return decimalOn(NOTE_THRESHOLD, date).orElse(null);
        return sheets.findById(sheetId).orElseThrow(() -> new SheetNotFoundException(sheetId));
    }

    /**
     * Set the clerk limit from the date (null: the sheet's today); a null limit means no limit. Every save is
     * recorded, even of the same value.
     */
    @Transactional
    public Sheet setClerkLimit(String sheetId, String user, BigDecimal limit, LocalDate from) {
        return record(sheetId, user, Sheet.CLERK_LIMIT, limit == null ? null : limit.toPlainString(), from, false);
    }

    /**
     * Set the floor, the least a live due of a claim dated from the date (null: the sheet's today) can be. Every save
     * is recorded, then the figures it moved.
     */
    @Transactional
    public Sheet setFloor(String sheetId, String user, BigDecimal floor, LocalDate from) {
        return record(sheetId, user, Sheet.FLOOR, floor.toPlainString(), from, true);
    }

    }

    /**
     * Set the proof threshold from the date (null: the sheet's today): a claim dated from then whose due is above it
     * cannot be settled or approved without a proof; a null threshold means none. Every save is recorded, even of the
     * same value.
     */
    @Transactional
    public Sheet setProofThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
        return record(sheetId, user, Sheet.PROOF_THRESHOLD, threshold == null ? null : threshold.toPlainString(), from,
                false);
    }

    /**
     * Set a grade's own proof threshold from the date (null: the sheet's today): a claim dated from then of a person
     * of the grade (on its date) is weighed against it in place of the sheet's; a null threshold means none (the
     * sheet's applies). Every save is recorded, even of the same value.
     */
    @Transactional
    public Sheet setGradeProofThreshold(String sheetId, String user, String grade, BigDecimal threshold,
            LocalDate from) {
        return record(sheetId, user, Sheet.gradeProofThresholdKey(grade),
                threshold == null ? null : threshold.toPlainString(), from, false);
    }

    /**
     * Set the note threshold from the date (null: the sheet's today): a claim dated from then whose due is above it
     * cannot be opened with an empty note; a null threshold means none. Every save is recorded, even of the same value.
     */
    @Transactional
    public Sheet setNoteThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
        // A part-settle judges four eyes and proof on the claim it split from, not on the new claim.
        if (status == ClaimStatus.SETTLED && !judgedOnOriginal && user.equals(claim.getOpenedBy())) {
            throw new ClaimSettledByOpenerException(id, user, "opened");
        }
        if (status == ClaimStatus.SETTLED && !judgedOnOriginal && user.equals(claim.getEditedBy())) {
            throw new ClaimSettledByOpenerException(id, user, "last edited");
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        if (status == ClaimStatus.SETTLED && !judgedOnOriginal) {
            requireProof(sheetId, person, claim);
        }
        if (status == ClaimStatus.OPEN) {
            requireUnflagged(sheetId, user, person, claim);
            requireNote(sheetId, person, claim);
            requireUnderCap(sheetId, claim);
            // A claim whose due is above the review threshold on its date waits for a steward's review instead.
            if (needsReview(sheetId, person, claim)) {
                status = ClaimStatus.REVIEW;
            }
        }
        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
            BigDecimal limit = settings.get(sheetId).getClerkLimit();
            BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                status = ClaimStatus.PENDING;
            }
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String due = status == ClaimStatus.SETTLED ? settle(sheetId, person, claim)
                : voidsSettled ? " reversed=" + shownDue(sheetId, person, claim) : "";
        claim.setStatus(status);
        if (status == ClaimStatus.VOID) {
            claim.setVoidReason(reason);
        }
        // Settled one at a time, a claim carries no batch; settled by a bulk settle, it carries that batch's number.
        if (status == ClaimStatus.SETTLED || status == ClaimStatus.PENDING) {
            claim.setSettleBatch(batch == null ? null : batch.getAsLong());
        }
        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
        String number = claim.getNumber();
        if (status == ClaimStatus.OPEN) {
            number = nextNumber(sheetId, claim.getDueBy());
            claim.setNumber(number);
            claim.setOpenedBy(user);
        }
        // Sent to REVIEW, it records who opened it and its review day but takes no number until it is reviewed.
        if (status == ClaimStatus.REVIEW) {
            claim.setOpenedBy(user);
    }

    @PutMapping("/proof-threshold")
    public SettingsView setProofThreshold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ProofThresholdRequest request) {
        return view(service.setProofThreshold(sheetId.trim(), user.trim(), request.proofThresholdValue(),
                request.from()));
    }

    @PutMapping("/proof-threshold/{grade}")
    public SettingsView setGradeProofThreshold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ProofThresholdRequest request) {
        return view(service.setGradeProofThreshold(sheetId.trim(), user.trim(), grade, request.proofThresholdValue(),
                request.from()));
    }

    @PutMapping("/note-threshold")
    public SettingsView setNoteThreshold(@PathVariable @NotBlank @Size(max = 100) String sheetId,

